repro_css:
@layer one, one.a, one.b;
@layer one { @layer b { .t { color: red } } }
@layer one.a { .t { color: green } }

.foo { -webkit-appearance: none; appearance: textfield; }
.c { backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(8px); }
@supports not (backdrop-filter: none) { .a { -webkit-backdrop-filter: none } }
